<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Product; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class ProductController extends Controller {
 public function index(Request $r){$q=Product::where('company_id',$r->user()->company_id)->with('category');if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('sku','like','%'.$r->search.'%'));if($r->filled('type'))$q->where('type',$r->type);if($r->filled('active'))$q->where('is_active',$r->boolean('active'));return $q->latest()->paginate($r->integer('per_page',20));}
 public function store(Request $r){$data=$r->validate(['name'=>'required|string|max:255','sku'=>['required','string','max:80',Rule::unique('products','sku')->where('company_id',$r->user()->company_id)],'category_id'=>['nullable','exists:product_categories,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\ProductCategory::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected category is invalid.');}],'type'=>'required|in:product,service','unit'=>'nullable|string|max:30','cost_price'=>'nullable|numeric|min:0','selling_price'=>'required|numeric|min:0','tax_rate'=>'nullable|numeric|min:0|max:100','stock_quantity'=>'nullable|numeric|min:0','minimum_stock'=>'nullable|numeric|min:0','track_stock'=>'boolean','is_active'=>'boolean']);$data['company_id']=$r->user()->company_id;if(($data['type']??null)==='service')$data['track_stock']=false;return response()->json(Product::create($data)->load('category'),201);}
 public function show(Request $r,Product $product){abort_unless($product->company_id===$r->user()->company_id,404);return $product->load('category');}
 public function update(Request $r,Product $product){abort_unless($product->company_id===$r->user()->company_id,404);$data=$r->validate(['name'=>'required|string|max:255','sku'=>['required','string','max:80',Rule::unique('products','sku')->ignore($product->id)->where('company_id',$r->user()->company_id)],'category_id'=>['nullable','exists:product_categories,id',function($attribute,$value,$fail)use($r){if($value && !\App\Models\ProductCategory::where('company_id',$r->user()->company_id)->whereKey($value)->exists())$fail('The selected category is invalid.');}],'type'=>'required|in:product,service','unit'=>'nullable|string|max:30','cost_price'=>'nullable|numeric|min:0','selling_price'=>'required|numeric|min:0','tax_rate'=>'nullable|numeric|min:0|max:100','stock_quantity'=>'nullable|numeric|min:0','minimum_stock'=>'nullable|numeric|min:0','track_stock'=>'boolean','is_active'=>'boolean']);if(($data['type']??null)==='service')$data['track_stock']=false;$product->update($data);return $product->fresh()->load('category');}
 public function destroy(Request $r,Product $product){abort_unless($product->company_id===$r->user()->company_id,404);if($product->saleItems()->exists()||$product->invoiceItems()->exists())return response()->json(['message'=>'Product has transaction history. Deactivate it instead of deleting.'],422);$product->delete();return response()->noContent();}
}
